command:example.dev:code:
# Script cleanup pattern
try {
    Connect-CWM @ConnectionParams
    # ... perform API operations ...
}
finally {
    Disconnect-CWM
    Write-Host "Cleanup complete"
}

$NewArguments = @{
    summary = "New ticket"
    company = @{ id = 250 }
    board = @{ id = 1 }
}
Invoke-CWMNewMaster -Arguments $NewArguments -Endpoint '/service/tickets'

$SearchArguments = @{
    condition = "company/id=250 and status/name='Open'"
    orderBy = "id desc"
    all = $true
}
Invoke-CWMSearchMaster -Arguments $SearchArguments -Endpoint '/service/tickets/search'

$SetArguments = @{
    name    = 'Monthly maintenance'
    summary = 'Monthly maintenance'
    board   = @{ id = 1 }
    status  = @{ id = 16 }
}
Invoke-CWMSetMaster -Arguments $SetArguments -Endpoint '/company/companies/250/serviceTemplates/15'

$UpdateArguments = @{
    PatchOperations = @(
        @{ op = 'replace'; path = 'summary'; value = 'New summary' }
        @{ op = 'replace'; path = 'status'; value = @{ id = 10 } }
        @{ op = 'remove'; path = 'contact' }
    )
}
Invoke-CWMUpdateMaster -Arguments $UpdateArguments -Endpoint '/service/tickets/12345'

# Minimal company creation
$company = @{
    identifier = "ACME"
    name = "Acme Corporation"
}
New-CWMCompany @company

$Template = @{
    parentId = 250
    name     = 'Monthly maintenance'
    summary  = 'Monthly maintenance'
    board    = @{ id = 1 }
    status   = @{ id = 16 }
}
New-CWMCompanyServiceTemplate @Template

$Article = @{
    title      = 'Printer offline'
    issue      = 'Printer shows offline on all workstations'
    resolution = 'Power cycle the printer and re-add the port.'
    board      = @{ id = 1 }
}
New-CWMKnowledgeBaseArticle @Article

$CatalogItem = @{
    identifier          = 'USB-C-DOCK'
    description         = 'USB-C docking station'
    customerDescription = 'USB-C docking station'
    subcategory         = @{ id = 3 }
    type                = @{ id = 1 }
    price               = 199
    cost                = 120
}
New-CWMProductCatalog @CatalogItem

$Ticket = @{
    summary            = 'Configure backups'
    project            = @{ id = 386 }
    phase              = @{ id = 12 }
    budgetHours        = 4
    initialDescription = 'Set up nightly backups for the new servers.'
}
New-CWMProjectTicket @Ticket

# Minimal ticket creation
$ticket = @{
    summary = "Password reset request"
    company = @{ id = 250 }
}
New-CWMTicket @ticket

# Full ticket with board, status, and description
$ticket = @{
    summary = "Server offline - urgent"
    company = @{ id = 250 }
    board = @{ id = 1 }
    status = @{ id = 10 }
    priority = @{ id = 3 }
    initialDescription = "Production server is not responding. Multiple users affected."
}
New-CWMTicket @ticket

# Ticket with contact information
$ticketParams = @{
    summary = "Email not working"
    company = @{ id = 250 }
    contact = @{ id = 500 }
    contactPhoneNumber = "555-1234"
    contactEmailAddress = "user@company.com"
    initialDescription = "User reports unable to send/receive email."
}
New-CWMTicket @ticketParams

$Template = @{
    parentId = 250
    id       = 15
    name     = 'Monthly maintenance'
    summary  = 'Monthly maintenance'
    board    = @{ id = 1 }
    status   = @{ id = 16 }
    company  = @{ id = 250 }
}
Set-CWMCompanyServiceTemplate @Template

Update-CWMAgreement -id 300 -PatchOperations @(
    @{ op = 'replace'; path = 'name'; value = 'Managed Services' }
    @{ op = 'replace'; path = 'customerPO'; value = 'PO-1234' }
)

Update-CWMAgreementAddition -parentId 300 -id 25 -PatchOperations @(
    @{ op = 'replace'; path = 'quantity'; value = 10 }
    @{ op = 'replace'; path = 'unitPrice'; value = 12.5 }
)

Update-CWMAgreementType -id 8 -PatchOperations @(
    @{ op = 'replace'; path = 'name'; value = 'Block Time (old)' }
    @{ op = 'replace'; path = 'inactiveFlag'; value = $true }
)

Update-CWMCallbackEntry -id 15 -PatchOperations @(
    @{ op = 'replace'; path = 'url'; value = 'https://example.com/hook' }
    @{ op = 'replace'; path = 'inactiveFlag'; value = $false }
)

Update-CWMCompany -id 250 -PatchOperations @(
    @{ op = 'replace'; path = 'name'; value = 'Acme Corporation Inc' }
    @{ op = 'replace'; path = 'phoneNumber'; value = '206-555-9999' }
    @{ op = 'replace'; path = 'status'; value = @{ id = 1 } }
)

Update-CWMCompanyConfiguration -id 5501 -PatchOperations @(
    @{ op = 'replace'; path = 'name'; value = 'FILESRV01' }
    @{ op = 'replace'; path = 'serialNumber'; value = 'ABC123' }
    @{ op = 'replace'; path = 'status'; value = @{ id = 2 } }
)

Update-CWMCompanyConfigurationTypeQuestionValue -typeId 12 -questionId 431 -valueId 3 -PatchOperations @(
    @{ op = 'replace'; path = 'value'; value = 'Windows Server 2022' }
    @{ op = 'replace'; path = 'defaultFlag'; value = $true }
)

Update-CWMCompanyContact -id 456 -PatchOperations @(
    @{ op = 'replace'; path = 'firstName'; value = 'Jane' }
    @{ op = 'replace'; path = 'title'; value = 'Office Manager' }
)

Update-CWMCompanyCustomNote -parentId 250 -id 7 -PatchOperations @(
    @{ op = 'replace'; path = 'note'; value = 'Customer is on hold' }
    @{ op = 'replace'; path = 'name'; value = 'On hold' }
)

Update-CWMCompanyServiceTemplate -parentId 250 -id 15 -PatchOperations @(
    @{ op = 'replace'; path = 'summary'; value = 'Monthly maintenance' }
    @{ op = 'replace'; path = 'priority'; value = @{ id = 4 } }
)

Update-CWMCompanySite -parentId 250 -id 12 -PatchOperations @(
    @{ op = 'replace'; path = 'addressLine1'; value = '100 Main St' }
    @{ op = 'replace'; path = 'city'; value = 'Tampa' }
    @{ op = 'remove'; path = 'addressLine2' }
)

Update-CWMCompanyTeam -parentId 250 -id 4 -PatchOperations @(
    @{ op = 'replace'; path = 'teamRole'; value = @{ id = 2 } }
    @{ op = 'replace'; path = 'accountManagerFlag'; value = $true }
)

Update-CWMContactCommunication -parentId 123 -id 9 -PatchOperations @(
    @{ op = 'replace'; path = 'value'; value = 'new@email.com' }
    @{ op = 'replace'; path = 'defaultFlag'; value = $true }
)

Update-CWMKnowledgeBaseArticle -id 42 -PatchOperations @(
    @{ op = 'replace'; path = 'title'; value = 'Reset VPN client' }
    @{ op = 'replace'; path = 'resolution'; value = 'Reinstall the client, then reboot.' }
)

Update-CWMMember -id 150 -PatchOperations @(
    @{ op = 'replace'; path = 'firstName'; value = 'Chris' }
    @{ op = 'replace'; path = 'title'; value = 'Engineer' }
