Update-CWMOpportunity -id 900 -PatchOperations @(
    @{ op = 'replace'; path = 'name'; value = 'Firewall refresh' }
    @{ op = 'replace'; path = 'status'; value = @{ id = 2 } }
)

Update-CWMOpportunityForecastItem -parentId 900 -id 2 -PatchOperations @(
    @{ op = 'replace'; path = 'revenue'; value = 1500 }
    @{ op = 'replace'; path = 'cost'; value = 900 }
)

Update-CWMProductAdjustment -id 40 -PatchOperations @(
    @{ op = 'replace'; path = 'reason'; value = 'Cycle count' }
    @{ op = 'replace'; path = 'closedFlag'; value = $true }
