Update-CWMProductCatalog -id 123 -PatchOperations @(
    @{ op = 'replace'; path = 'price'; value = 49.99 }
    @{ op = 'replace'; path = 'cost'; value = 30 }
    @{ op = 'replace'; path = 'description'; value = 'Updated description' }
