Update-CWMProductPickingShippingDetail -parentId 12 -id 77 -PatchOperations @(
    @{ op = 'replace'; path = 'pickedQuantity'; value = 2 }
    @{ op = 'replace'; path = 'shippedQuantity'; value = 2 }
