Update-CWMServiceTemplateResource -parentId 15 -id 3 -PatchOperations @(
    @{ op = 'replace'; path = 'member'; value = @{ identifier = 'jdoe' } }
    @{ op = 'replace'; path = 'isTicketOwner'; value = $true }
